import { normalizeWords, joinWords } from './helper';

export default {
  id: 'words',
  name: 'Words',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'normalize_words',
        version: '1.0.0',
        description: 'Normalize a word list: lowercase, deduplicate and sort alphabetically.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            text: { type: 'string', description: 'Raw text containing words separated by spaces, commas or newlines.' }
          },
          required: ['text']
        },
        outputSchema: {
          type: 'object',
          properties: {
            words: { type: 'array', items: { type: 'string' } },
            joined: { type: 'string' }
          },
          required: ['words', 'joined']
        },
        async handler(args: unknown) {
          const { text } = args as { text: string };
          const words = normalizeWords(text);
          return { ok: true, data: { words, joined: joinWords(words) } };
        }
      }
    });
  }
};

